import { expect, test } from "vitest";
import { waitUntil } from "../waitUntil";

async function eventually(check: () => boolean, deadlineMs = 2000) {
  const start = Date.now();
  while (!check()) {
    if (Date.now() - start > deadlineMs) throw new Error("condition not met before deadline");
    await new Promise((r) => setTimeout(r, 10));
  }
}

test("waitUntil resolves once the flag flips", async () => {
  let ready = false;
  const p = waitUntil(() => ready);
  ready = true;
  await p;
  await eventually(() => ready);
  expect(ready).toBe(true);
});

